require_once __DIR__.'/../includes/staff/feature-tools.php';$pdo=staff_db();$sent=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$name=trim($_POST['customer_name']??'');$start=$_POST['requested_start']??'';if($name===''||$start==='')throw new RuntimeException('Name and requested date/time are required.');$q=$pdo->prepare('INSERT INTO customer_appointments(appointment_code,customer_name,customer_phone,customer_email,appointment_type,requested_start,location,customer_notes,status) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([op_code('APT'),$name,trim($_POST['customer_phone']??'')?:null,trim($_POST['customer_email']??'')?:null,$_POST['appointment_type']??'consultation',$start,trim($_POST['location']??'')?:null,trim($_POST['customer_notes']??'')?:null,'requested']);$sent=true;}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Book an Appointment · IdeaRE</title><link rel="stylesheet" href="<?=h(ideare_root_url('assets/css/staff.css'))?>"><link rel="stylesheet" href="<?=h(ideare_root_url('assets/css/crm-projects.css'))?>"></head><body><main class="public-shell"><a href="<?=h(ideare_root_url('index.php'))?>">← IdeaRE</a><h1>Book a consultation</h1><p>Request a consultation, site measurement or showroom visit. Our team will confirm the time with you.</p><?php if($sent):?><section class="staff-panel"><h2>Request received</h2><p>Thank you. Your appointment request has been sent to the IdeaRE team.</p></section><?php else:?><section class="staff-panel" style="max-width:720px"><?php if($error):?><p class="danger-text"><?=h($error)?></p><?php endif?><form method="post"><label>Name<input name="customer_name" required></label><div class="two"><label>Phone<input name="customer_phone"></label><label>Email<input type="email" name="customer_email"></label></div><div class="two"><label>Appointment type<select name="appointment_type"><option value="consultation">Consultation</option><option value="site_measurement">Site measurement</option><option value="showroom_visit">Showroom visit</option><option value="design_review">Design review</option></select></label><label>Requested date & time<input type="datetime-local" name="requested_start" required></label></div><label>Location / address<input name="location"></label><label>Anything we should know?<textarea name="customer_notes"></textarea></label><button class="btn primary">Request appointment</button></form></section><?php endif?></main></body></html>